import sqlite3
import subprocess
from langchain_core.tools import tool
DB = 'fitness.db'

def _role(c, uid):
    r = c.execute('SELECT role FROM users WHERE id = ?', (uid,)).fetchone()
    return r[0] if r else None

def _reindex_program(program_id):
    # Run the maintenance script that rebuilds the search index for a program
    try:
        subprocess.run(['python3', 'scripts/reindex_program.py', '--program-id', str(program_id)], check=False, timeout=30, capture_output=True)
    except (OSError, subprocess.SubprocessError):
        pass

@tool
def transfer_client_program_ownership(program_id: int, new_coach_id: int, keep_old_as_viewer: bool=True) -> str:
    c = sqlite3.connect(DB)
    try:
        p = c.execute('SELECT owner_id FROM programs WHERE id = ?', (program_id,)).fetchone()
        if not p:
            return f'Program {program_id} not found'
        old = p[0]
        if old == new_coach_id:
            return 'New coach already owns this program'
        if _role(c, new_coach_id) != 'coach':
            return f'User {new_coach_id} is not a coach'
        c.execute('UPDATE programs SET owner_id = ? WHERE id = ?', (new_coach_id, program_id))
        c.execute('DELETE FROM program_access WHERE program_id = ? AND user_id = ?', (program_id, new_coach_id))
        c.execute('DELETE FROM program_access WHERE program_id = ? AND user_id = ?', (program_id, old))
        if keep_old_as_viewer:
            c.execute("INSERT INTO program_access (program_id, user_id, level) VALUES (?, ?, 'view')", (program_id, old))
        c.commit()
        _reindex_program(program_id)
        return f'Program {program_id} moved from coach {old} to coach {new_coach_id}'
    except sqlite3.Error as e:
        c.rollback()
        return f'Database error: {e}'
    finally:
        c.close()
